const sections = [
  ...HOME_SECTIONS.map((section, index) => ({ ...section, page_slug: 'home', sort_order: index })),
  { ...SERVICE_TEMPLATE_SECTION, page_slug: 'services', sort_order: 0 }
].map((section) =>
  stamp({ id: seedId(`section:${section.page_slug}:${section.key}`), enabled: true, ...section })
);

// Services: base fields + Arabic overrides + detail-page content as unlimited child items.
const services = SITE_CONTENT.services.map((service, index) => {
  const ar = SITE_CONTENT_AR.services[service.id] || {};
  const details = SERVICE_DETAILS[service.id];
  const serviceId = seedId('service:' + service.id);
  const items = [];
  const push = (kind, list, map) =>
    list.forEach((entry, i) =>
      items.push(stamp({ id: seedId(`service-item:${service.id}:${kind}:${i}`), service_id: serviceId, kind, sort_order: i, ...map(entry, i) }))
    );
  push('deliverable', service.deliverables, (title, i) => ({
    title_en: title,
    title_ar: ar.deliverables?.[i] || title,
    body_en: details.en.offers[i]?.[1] || '',
    body_ar: details.ar.offers[i]?.[1] || ''
  }));
  push('process', details.en.process, ([title, body], i) => ({
    title_en: title, body_en: body, title_ar: details.ar.process[i][0], body_ar: details.ar.process[i][1]
  }));
  push('value', details.en.value, ([title, body], i) => ({
    title_en: title, body_en: body, title_ar: details.ar.value[i][0], body_ar: details.ar.value[i][1]
  }));
  push('faq', details.en.faq, ([title, body], i) => ({
    title_en: title, body_en: body, title_ar: details.ar.faq[i][0], body_ar: details.ar.faq[i][1]
  }));
  return stamp({
    id: serviceId,
    slug: service.id,
    sort_order: index,
    published: true,
    name_en: service.title,
    name_ar: ar.title || service.title,
    tagline_en: service.tagline,
    tagline_ar: ar.tagline || service.tagline,
    description_en: service.description,
    description_ar: ar.description || service.description,
    overview_en: details.en.overview.join('\n\n'),
    overview_ar: details.ar.overview.join('\n\n'),
    color: service.color,
    icon_url: service.icon,
    hero_image_url: service.image || '',
    work_link: service.workLink || '',
    whatsapp_message_en: details.whatsapp.en,
    whatsapp_message_ar: details.whatsapp.ar,
    seo_title_en: details.seo.en.title,
    seo_title_ar: details.seo.ar.title,
    seo_description_en: details.seo.en.description,
    seo_description_ar: details.seo.ar.description,
    og_image_url: '',
    items
  });
});

// Work collections → sliders; every video item → a slide.
const COLLECTIONS = [
  { key: 'reels', title: ['REELS', 'ريلز'], nav: ['Reels', 'ريلز'], text: ['Short-form stories. Made for the moment.', 'حكايات قصيرة. معمولة للحظة.'] },
  { key: 'films', title: ['FILMS', 'أفلام'], nav: ['Films', 'أفلام'], text: ['Cinematic thinking. Stories worth staying for.', 'رؤية سينمائية. وحكايات تستاهل وقتك.'] },
  { key: 'sketches', title: ['SKETCHES', 'سكتشات'], nav: ['Sketches', 'سكتشات'], text: ['Characters, scenes and ideas with personality.', 'شخصيات ومشاهد وأفكار ليها روح.'] }
];
const sliders = COLLECTIONS.map((collection, index) => {
  const sliderId = seedId('slider:' + collection.key);
  return stamp({
    id: sliderId,
    key: collection.key,
    sort_order: index,
    enabled: true,
    title_en: collection.title[0],
    title_ar: collection.title[1],
    nav_label_en: collection.nav[0],
    nav_label_ar: collection.nav[1],
    description_en: collection.text[0],
    description_ar: collection.text[1],
    slides: WORK_ITEMS.filter((item) => item.category === collection.key && item.src).map((item, i) =>
      stamp({
        id: seedId(`slide:${collection.key}:${item.src}`),
        slider_id: sliderId,
        sort_order: i,
        enabled: true,
        title_en: item.title,
        title_ar: item.titleAr || item.title,
        description_en: '',
        description_ar: '',
        label_en: item.label || collection.key.toUpperCase(),
        label_ar: item.labelAr || item.label || collection.key.toUpperCase(),
        video_url: item.src,
        image_url: '',
        poster_url: item.poster || '',
        cta_label_en: '',
        cta_label_ar: '',
        cta_url: ''
      })
    )
  });
});

const clients = CLIENTS.filter((client) => client.name && client.logo).map((client, index) =>
  stamp({
    id: seedId('client:' + client.logo),
    sort_order: index,
    enabled: true,
    name_en: client.name,
    name_ar: client.nameAr || client.name,
    logo_url: client.logo,
    url: '',
    theme: client.theme || 'light'
  })
);

